package ru.ascdev.remotehub;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.net.*;import android.util.Base64;import java.io.*;import java.util.*;import org.json.*;
final class Tools {
 final Context c;Tools(Context c){this.c=c;}
 static JSONArray names(){return new JSONArray(Arrays.asList("machine_info","list_directory","stat_path","android_apps","android_launch","android_ui_tree","android_ui_action","android_gesture","android_file_read","android_file_write"));}
 static String platform(){return "Android "+Build.VERSION.RELEASE+" (API "+Build.VERSION.SDK_INT+")";}
 JSONObject info()throws Exception{Intent b=c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();c.getSystemService(ActivityManager.class).getMemoryInfo(m);StatFs s=new StatFs(Environment.getExternalStorageDirectory().getPath());ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);NetworkCapabilities n=cm.getNetworkCapabilities(cm.getActiveNetwork());return Api.obj("platform",platform(),"name",Build.MANUFACTURER+" "+Build.MODEL,"agent_version",Config.VERSION,"battery_percent",b==null?-1:100*b.getIntExtra("level",0)/Math.max(1,b.getIntExtra("scale",100)),"charging",b!=null&&b.getIntExtra("plugged",0)!=0,"battery_temperature_c",b==null?JSONObject.NULL:b.getIntExtra("temperature",0)/10.0,"memory_total",m.totalMem,"memory_available",m.availMem,"storage_total",s.getTotalBytes(),"storage_available",s.getAvailableBytes(),"wifi",n!=null&&n.hasTransport(NetworkCapabilities.TRANSPORT_WIFI),"mobile",n!=null&&n.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR),"screen_on",c.getSystemService(PowerManager.class).isInteractive(),"locked",c.getSystemService(KeyguardManager.class).isKeyguardLocked(),"ui_enabled",UiService.instance!=null,"all_files",Environment.isExternalStorageManager(),"file_root",root().getPath());}
 File root()throws IOException{File f=Environment.isExternalStorageManager()?Environment.getExternalStorageDirectory():c.getExternalFilesDir(null);if(f==null)throw new IOException("Storage unavailable");return f.getCanonicalFile();}
 File path(String p)throws IOException{File root=root();File f=p.equals("/")?root:new File(p);if(!f.isAbsolute())f=new File(root,p);f=f.getCanonicalFile();String r=root.getPath(),v=f.getPath();if(!v.equals(r)&&!v.startsWith(r+"/"))throw new SecurityException("Outside shared storage");String privateDir=new File(Environment.getExternalStorageDirectory(),"Android").getCanonicalPath();if(Environment.isExternalStorageManager()&&(v.equals(privateDir)||v.startsWith(privateDir+"/")))throw new SecurityException("Private app directories excluded");return f;}
 static JSONObject result(Object o)throws Exception{return Api.obj("content",new JSONArray().put(Api.obj("type","text","text",o.toString())),"isError",false);}
 static JSONObject error(String s){try{return Api.obj("content",new JSONArray().put(Api.obj("type","text","text",s)),"isError",true);}catch(Exception e){return new JSONObject();}}
 JSONObject handle(String t,JSONObject a){try{if(a==null)a=new JSONObject();if(!new Config(c).enabled())return error("Remote control stopped");switch(t){case "machine_info":return result(info());case "list_directory":{File f=path(a.getString("path"));File[] children=f.listFiles();if(children==null)throw new IOException("Directory not readable");Arrays.sort(children,Comparator.comparing(File::getName));JSONArray list=new JSONArray();int max=Math.min(200,Math.max(1,a.optInt("limit",200)));for(File child:children){if(list.length()>=max)break;try{File checked=path(child.getPath());list.put(stat(checked));}catch(SecurityException ignored){}}return result(Api.obj("path",f.getPath(),"entries",list,"truncated",children.length>list.length()));}
 case "stat_path":return result(stat(path(a.getString("path"))));
 case "android_apps":{Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);JSONArray out=new JSONArray();HashSet<String> seen=new HashSet<>();for(ResolveInfo r:c.getPackageManager().queryIntentActivities(q,0)){String p=r.activityInfo.packageName;if(seen.add(p))out.put(Api.obj("package",p,"label",r.loadLabel(c.getPackageManager()).toString()));}return result(out);}
 case "android_launch":{Intent i=c.getPackageManager().getLaunchIntentForPackage(a.getString("package"));if(i==null)throw new IllegalArgumentException("Application not launchable");return result(ui().launch(i));}
 case "android_ui_tree":return result(ui().tree());case "android_ui_action":return result(ui().action(a));case "android_gesture":return result(ui().gesture(a));
 case "android_file_read":{File f=path(a.getString("path"));long off=a.optLong("offset",0);int len=a.optInt("length",32768);if(off<0||len<1||len>65536)throw new IllegalArgumentException("Invalid range");try(RandomAccessFile r=new RandomAccessFile(f,"r")){if(off>r.length())throw new IllegalArgumentException("Offset beyond EOF");r.seek(off);byte[] data=new byte[(int)Math.min(len,r.length()-off)];r.readFully(data);return result(Api.obj("data_base64",Base64.encodeToString(data,2),"offset",off,"next_offset",off+data.length,"size",r.length(),"eof",off+data.length==r.length()));}}
 case "android_file_write":{File f=path(a.getString("path"));long off=a.getLong("offset");String encoded=a.getString("data_base64");if(encoded.length()>88000||off<0)throw new IllegalArgumentException("Invalid chunk");byte[] data=Base64.decode(encoded,2);if(data.length>65536)throw new IllegalArgumentException("Chunk too large");if(off==0){if(!f.createNewFile())throw new IOException("Destination exists; use a new filename");}else if(!f.isFile()||f.length()!=off)throw new IOException("Offset mismatch");try(RandomAccessFile r=new RandomAccessFile(f,"rw")){if(r.length()!=off)throw new IOException("Offset mismatch");r.seek(off);r.write(data);r.getFD().sync();return result(Api.obj("next_offset",r.length(),"written",data.length));}}
 default:return error("Unsupported tool");}}catch(Exception e){Throwable x=e instanceof java.util.concurrent.ExecutionException&&e.getCause()!=null?e.getCause():e;return error(x.getClass().getSimpleName()+": "+x.getMessage());}}
 UiService ui(){UiService u=UiService.instance;if(u==null)throw new IllegalStateException("Enable ASC Remote Hub accessibility service on device");return u;}
 JSONObject stat(File f)throws Exception{if(!f.exists())throw new FileNotFoundException(f.getPath());return Api.obj("name",f.getName(),"path",f.getPath(),"type",f.isDirectory()?"directory":"file","size",f.length(),"modified",f.lastModified()/1000);}
}